/// @brief 仅包装一只演员的世界出生配置；参数不含原坐标或子程序编号，种子逐实例固定。
SpawnActors Spawn(Vector3 position,const behavior::Pattern& pattern,float health,int score,int item,
                  bool mirror,bool randomX,unsigned seed,VisualId visual) {
    return {behavior::Spawn{.position=position,.pattern=pattern,.mirrored=mirror,.randomX=randomX,
        .sourceHealth=health,.sourceScore=score,.seed=seed,.sourceItem=item,.visual=visual,.hitRadius=0.625F,
        .bulletBase=kNativeBulletBase,.laserBase=kNativeLaserBase,.defeatBase=kNativeDefeat,.fallback=kBlueBullet,
        .retirementHeights=Vector2{-10.5F,10.5F}},1,0};
}
